/**
 * Official Emblem & Logo for Platform «مرحلة التأهيل»
 * Source: the approved circular badge artwork (pen, open book, laurel branch,
 * book stack, "مرحلة التأهيل" wordmark and "طلب علم .. بناء قلب .. وصناعة أمة" motto).
 * Stored inline as a base64 PNG data URI so it works offline with no extra request,
 * exactly like a user-supplied custom logo (see Storage.saveCustomLogo).
 */

const OFFICIAL_TAHEEL_LOGO_DATA_URL = "data:image/png;base64,";

/**
 * Returns the official logo as a data URI for use in <img> tags and PDF/report exports.
 */
export function getOfficialLogoDataUrl() {
  return OFFICIAL_TAHEEL_LOGO_DATA_URL;
}
